  "ui.figuresTables": { zh: "图表定位结果", en: "Figures & Tables", ja: "図表の検索結果", ru: "Результаты поиска рисунков и таблиц", es: "Resultados de figuras y tablas" , fr: "Figures et tableaux", de: "Abbildungen & Tabellen", pt: "Figuras e tabelas", ko: "그림 및 표", ar: "الأشكال والجداول" },
