  "ui.doubleClickBookmarkTextToEditIt": { zh: "双击书签文字可直接编辑", en: "Double-click bookmark text to edit it", ja: "ブックマーク名をダブルクリックして編集", ru: "Дважды щёлкните текст закладки для редактирования", es: "Haz doble clic en el texto del marcador para editarlo" , fr: "Double-cliquer sur le texte du signet pour le modifier il", de: "Doppelklicken Sie auf den Lesezeichentext, um ihn zu bearbeiten", pt: "Clique duas vezes no texto do marcador para editá-lo", ko: "북마크 텍스트를 두 번 클릭하여 편집하기", ar: "انقر نقرًا مزدوجًا على نص الإشارة المرجعية لتعديله" },
  "ui.doubleClickToEditUseTheDeleteButtonToRemove": { zh: "双击编辑；使用删除按钮移除单条书签", en: "Double-click to edit; use the delete button to remove one bookmark", ja: "ダブルクリックで編集、削除ボタンで個別に削除", ru: "Дважды щёлкните для правки; кнопка удаления удаляет одну закладку", es: "Haz doble clic para editar; usa el botón de eliminar para quitar un marcador" , fr: "Double-cliquez pour modifier ; utilisez le bouton Supprimer pour retirer un signet", de: "Doppelklicken zum Bearbeiten Verwenden Sie die Entf-Taste, um ein Lesezeichen zu entfernen.", pt: "Clique duas vezes para editar; Use o botão Excluir para remover um marcador", ko: "두 번 클릭하여 편집하기 삭제 버튼을 사용하여 책갈피 하나를 제거하세요.", ar: "انقر نقرًا مزدوجًا للتعديل؛ استخدم زر الحذف لإزالة إشارة مرجعية واحدة" },
