  "ui.recognizeBookmarks": { zh: "识别书签", en: "Recognize Bookmarks", ja: "ブックマークを認識", ru: "Распознать закладки", es: "Reconocer marcadores" , fr: "Reconnaître les signets", de: "Lesezeichen erkennen", pt: "Reconhecer marcadores", ko: "책갈피 인식", ar: "التعرف على الإشارات المرجعية" },
  "ui.detectHeadingLevelsFromTextAndTypographyThenWriteStandard": { zh: "按标题文字和排版识别层级，并写入标准 PDF 书签。", en: "Detect heading levels from text and typography, then write standard PDF bookmarks.", ja: "見出しの文字と書式から階層を検出し、標準 PDF ブックマークとして書き込みます。", ru: "Определяет уровни заголовков по тексту и оформлению и записывает стандартные закладки PDF.", es: "Detecta niveles de títulos por texto y formato y los escribe como marcadores PDF estándar." , fr: "Détecter les niveaux de titre à partir du texte et de la typographie, puis créer des signets PDF standard.", de: "Überschriftenebenen anhand von Text und Typografie erkennen und anschließend Standard-PDF-Lesezeichen erstellen.", pt: "Detectar níveis de título a partir do texto e da tipografia e, em seguida, gravar marcadores PDF padrão.", ko: "텍스트와 서체에서 제목 레벨을 감지한 다음 표준 PDF 책갈피를 작성합니다.", ar: "اكتشاف مستويات العناوين من النص والطباعة، ثم كتابة إشارات مرجعية قياسية لملفات PDF." },
  "ui.closeBookmarkRecognition": { zh: "关闭识别书签", en: "Close bookmark recognition", ja: "ブックマーク認識を閉じる", ru: "Закрыть распознавание закладок", es: "Cerrar reconocimiento de marcadores" , fr: "Fermer la reconnaissance des signets", de: "Lesezeichenerkennung deaktivieren", pt: "Desativar reconhecimento de marcadores", ko: "책갈피 인식 닫기", ar: "إغلاق خاصية التعرف على الإشارات المرجعية" },
  "ui.recognitionRules": { zh: "识别规则", en: "Recognition Rules", ja: "認識ルール", ru: "Правила распознавания", es: "Reglas de reconocimiento" , fr: "Règles de reconnaissance", de: "Erkennungsregeln", pt: "Regras de reconhecimento", ko: "인식 규칙", ar: "قواعد التعرف" },
  "ui.combineRulesAsNeededDisableUnsuitableRulesToReduceFalse": { zh: "可组合使用；关闭不适合本文档的规则可减少误识别。", en: "Combine rules as needed. Disable unsuitable rules to reduce false matches.", ja: "ルールは組み合わせ可能です。文書に合わないルールを無効にすると誤検出を減らせます。", ru: "Правила можно сочетать. Отключайте неподходящие, чтобы уменьшить ложные совпадения.", es: "Combina las reglas según convenga. Desactiva las inadecuadas para reducir falsos positivos." , fr: "Combiner les règles selon les besoins. Désactiver les règles inadaptées pour réduire les faux positifs.", de: "Regeln nach Bedarf kombinieren. Ungeeignete Regeln deaktivieren, um Fehlalarme zu reduzieren.", pt: "Combinar regras conforme necessário. Desativar regras inadequadas para reduzir falsos positivos.", ko: "필요에 따라 규칙을 결합하세요. 잘못된 일치를 줄이려면 적합하지 않은 규칙을 비활성화하세요.", ar: "دمج القواعد حسب الحاجة. تعطيل القواعد غير المناسبة لتقليل التطابقات الخاطئة." },
  "ui.maximumBookmarkDepth": { zh: "最大书签识别深度", en: "Maximum Bookmark Depth", ja: "ブックマークの最大階層", ru: "Максимальная глубина закладок", es: "Profundidad máxima de marcadores" , fr: "Profondeur maximale des signets", de: "Maximale Lesezeichentiefe", pt: "Profundidade máxima do marcador", ko: "최대 책갈피 깊이", ar: "أقصى عمق للإشارات المرجعية" },
  "ui.numberedHeadingsDeeperThanThisLevelWillNotBeWritten": { zh: "超过所选层级的编号不会写入", en: "Numbered headings deeper than this level will not be written", ja: "選択した階層より深い番号付き見出しは書き込みません", ru: "Нумерованные заголовки глубже выбранного уровня не записываются", es: "Los títulos numerados que superen este nivel no se escribirán" , fr: "Les titres numérotés de niveau supérieur à celui-ci ne seront pas créés", de: "Nummerierte Überschriften, die tiefer als diese Ebene liegen, werden nicht erstellt.", pt: "Títulos numerados com profundidade superior a este nível não serão gravados", ko: "이 레벨보다 깊은 번호가 매겨진 제목은 작성되지 않습니다.", ar: "لن تُكتب العناوين المرقمة التي يزيد عمقها عن هذا المستوى" },
