  "ui.onePerLineAddRecurringHeadingsUsedBySpecialistDocuments": { zh: "每行一个；用于补充专业文档中的固定标题", en: "One per line; add recurring headings used by specialist documents", ja: "1 行に 1 つ。専門文書で使う定型見出しを追加できます", ru: "По одному на строку; добавьте типовые заголовки специальных документов", es: "Uno por línea; añade títulos fijos de documentos especializados" , fr: "Un par ligne ; Ajouter des titres récurrents utilisés par les documents spécialisés", de: "Ein Begriff pro Zeile; Wiederkehrende Überschriften für Fachdokumente hinzufügen", pt: "Um por linha; Adicionar títulos recorrentes usados ​​por documentos especializados", ko: "한 줄에 하나씩 전문 문서에서 자주 사용되는 제목을 추가합니다.", ar: "مصطلح واحد في كل سطر. إضافة العناوين المتكررة المستخدمة في المستندات المتخصصة" },
  "ui.forExampleDataAvailabilityEthicsStatementTerminology": { zh: "例如：数据可用性\n伦理声明\n术语定义", en: "For example: Data availability\nEthics statement\nTerminology", ja: "例：データの利用可能性\n倫理声明\n用語定義", ru: "Например: Доступность данных\nЭтическое заявление\nТермины", es: "Por ejemplo: Disponibilidad de datos\nDeclaración ética\nTerminología" , fr: "Par exemple : Disponibilité des données \n Déclaration d’éthique \n Terminologie", de: "Beispiel: Datenverfügbarkeit \n Ethikerklärung \n Terminologie", pt: "Por exemplo: Disponibilidade de dados \n Declaração de ética \n Terminologia", ko: "예: 데이터 가용성 \n 윤리 강령 \n 용어집", ar: "مثال: توفر البيانات \n بيان الأخلاقيات \n المصطلحات" },
