  "shortcut.navigationHint": { zh: "{zoom} + 滚轮缩放；{page} + 左右方向键快速翻页。", en: "{zoom} + wheel zooms; {page} + Left/Right changes pages.", ja: "{zoom}＋ホイールで拡大縮小し、{page}＋左右矢印でページを切り替えます。", ru: "{zoom} + колесо меняет масштаб; {page} + стрелки переключают страницы.", es: "{zoom} + rueda amplía; {page} + flechas cambia de página." , fr: "{zoom} + molette : zoom ; {page} + Gauche/Droite : changement de page.", de: "{zoom} + Mausrad: Zoomen; {page} + Links/Rechts: Seitenwechsel", pt: "{zoom} + a roda do mouse amplia; {page} + Esquerda/Direita alterna entre páginas.", ko: "{zoom} + 휠 확대/축소; {page} + 좌/우 이동", ar: "{zoom} + عجلة التكبير/التصغير؛ {page} + يمين/يسار لتغيير الصفحات." },
  "shortcut.annotationSelectionHint": { zh: "拖动框选 · {add}：加选 · Shift：连选 · {remove}：删除", en: "Drag to select · {add}: add · Shift: range · {remove}: remove", ja: "ドラッグ：選択 · {add}：追加 · Shift：範囲 · {remove}：削除", ru: "Перетащить: выбрать · {add}: добавить · Shift: диапазон · {remove}: удалить", es: "Arrastrar: seleccionar · {add}: añadir · Shift: rango · {remove}: eliminar" , fr: "Glisser : sélectionner · {add} : ajouter · Maj : plage · {remove} : supprimer", de: "Ziehen: auswählen · {add}: hinzufügen · Umschalt: Bereich · {remove}: löschen", pt: "Arrastar: selecionar · {add}: adicionar · Shift: intervalo · {remove}: remover", ko: "드래그: 선택 · {add}: 추가 · Shift: 범위 · {remove}: 삭제", ar: "اسحب للتحديد · {add}: إضافة · Shift: نطاق · {remove}: حذف" },
  "close.app": { zh: "有 {count} 个文档包含未保存的修改，确定关闭 PDFuck 吗？", en: "{count} document(s) have unsaved changes. Close PDFuck?", ja: "未保存の変更がある文書が {count} 件あります。PDFuck を閉じますか？", ru: "{count} документ(ов) содержит несохранённые изменения. Закрыть PDFuck?", es: "{count} documento(s) tiene(n) cambios sin guardar. ¿Cerrar PDFuck?" , fr: "{count} document(s) contient(nt) des modifications non enregistrées. Fermer PDFuck ?", de: "{count} Dokument(e) enthalten ungespeicherte Änderungen. PDFuck schließen?", pt: "{count} documento(s) têm alterações não salvas. Fechar o PDFuck?", ko: "{count} 문서에 저장되지 않은 변경 사항이 있습니다. PDFuck을 닫으시겠습니까?", ar: "{count} المستندات التي تحتوي على تغييرات غير محفوظة. إغلاق PDFuck؟" },
  "close.document": { zh: "{name} 有未保存的修改，确定关闭这个文档标签吗？", en: "{name} has unsaved changes. Close this document tab?", ja: "{name} には未保存の変更があります。この文書タブを閉じますか？", ru: "В документе {name} есть несохранённые изменения. Закрыть эту вкладку?", es: "{name} tiene cambios sin guardar. ¿Cerrar esta pestaña de documento?" , fr: "{name} contient(nt) des modifications non enregistrées. Fermer cet onglet ?", de: "{name} enthält ungespeicherte Änderungen. Dokument-Tab schließen?", pt: "{name} tem alterações não salvas. Fechar esta aba do documento?", ko: "{name}에 저장되지 않은 변경 사항이 있습니다. 이 문서 탭을 닫으시겠습니까?", ar: "{name} يحتوي على تغييرات غير محفوظة. هل تريد إغلاق علامة تبويب هذا المستند؟" },
  "close.multiple": { zh: "当前打开了 {count} 个文档。关闭 PDFuck 会同时关闭全部文档，是否继续？", en: "{count} documents are open. Closing PDFuck will close all of them. Continue?", ja: "{count} 件の文書が開いています。PDFuck を閉じるとすべて閉じられます。続行しますか？", ru: "Открыто документов: {count}. При закрытии PDFuck все они будут закрыты. Продолжить?", es: "Hay {count} documentos abiertos. Al cerrar PDFuck se cerrarán todos. ¿Continuar?" , fr: "{count} documents sont ouverts. Fermer PDFuck les fermera tous. Continuer ?", de: "{count} Dokumente sind geöffnet. Durch Schließen von PDFuck werden alle geschlossen. Fortfahren?", pt: "{count} documentos estão abertos. Fechar o PDFuck fechará todos eles. Continuar?", ko: "{count} 문서가 열려 있습니다. PDFuck을 닫으면 모든 문서가 닫힙니다. 계속하시겠습니까?", ar: "{count} مستندات مفتوحة. سيؤدي إغلاق PDFuck إلى إغلاقها جميعًا. هل تريد المتابعة؟" },
  "close.multipleDirty": { zh: "当前打开了 {count} 个文档，其中 {dirty} 个包含未保存的修改。关闭 PDFuck 会同时关闭全部文档，是否继续？", en: "{count} documents are open, and {dirty} have unsaved changes. Closing PDFuck will close all of them. Continue?", ja: "{count} 件の文書が開いており、そのうち {dirty} 件に未保存の変更があります。PDFuck を閉じるとすべて閉じられます。続行しますか？", ru: "Открыто документов: {count}; несохранённые изменения есть в {dirty}. При закрытии PDFuck все документы будут закрыты. Продолжить?", es: "Hay {count} documentos abiertos y {dirty} tienen cambios sin guardar. Al cerrar PDFuck se cerrarán todos. ¿Continuar?" , fr: "{count} documents sont ouverts et {dirty} contient(nt) des modifications non enregistrées. Fermer PDFuck les fermera tous. Continuer ?", de: "{count} Dokumente sind geöffnet, und {dirty} enthält ungespeicherte Änderungen. Durch Schließen von PDFuck werden alle geschlossen. Fortfahren?", pt: "{count} documentos estão abertos e {dirty} tem alterações não salvas. Fechar o PDFuck fechará todos eles. Continuar?", ko: "{count} 문서가 열려 있고 {dirty} 문서에는 저장되지 않은 변경 사항이 있습니다. PDFuck을 닫으면 모든 문서가 닫힙니다. 계속하시겠습니까?", ar: "{count} مستندات مفتوحة، و{dirty} يحتوي على تغييرات غير محفوظة. سيؤدي إغلاق PDFuck إلى إغلاقها جميعًا. هل تريد المتابعة؟" },
  "page.deleteSummary": { zh: "将删除 {remove} 页，保留 {keep} 页。", en: "Delete {remove} pages and keep {keep} pages.", ja: "{remove} ページを削除し、{keep} ページを保持します。", ru: "Удалить страниц: {remove}; оставить: {keep}.", es: "Se eliminarán {remove} páginas y se conservarán {keep}." , fr: "Supprimer {remove} pages et conserver {keep} pages.", de: "{remove} Seiten löschen und {keep} Seiten behalten.", pt: "Excluir páginas {remove} e manter páginas {keep}.", ko: "{remove} 페이지를 삭제하고 {keep} 페이지는 유지합니다.", ar: "حذف صفحات {remove} والاحتفاظ بصفحات {keep}." },
