export type TranslationKey = keyof typeof messages

export function isInterfaceLanguage(value: unknown): value is InterfaceLanguage {
  return typeof value === 'string' && INTERFACE_LANGUAGES.includes(value as InterfaceLanguage)
}

export function hasTranslationKey(value: string): value is TranslationKey {
  return Object.prototype.hasOwnProperty.call(messages, value)
}

export function translateMessage(language: InterfaceLanguage, key: TranslationKey, values: Record<string, string | number> = {}): string {
  return messages[key][language].replace(/\{(\w+)\}/g, (_, name: string) => String(values[name] ?? '{' + name + '}'))
}

const chineseUiKeys = new Map<string, TranslationKey>()
for (const key of Object.keys(messages) as TranslationKey[]) {
  if (key.startsWith('ui.') && !chineseUiKeys.has(messages[key].zh)) chineseUiKeys.set(messages[key].zh, key)
}

/** Localize deferred status/error text without touching PDF text, paths, or user content. */
export function translateStoredUiText(language: InterfaceLanguage, value: string): string {
  if (hasTranslationKey(value)) return translateMessage(language, value)
  if (language === 'zh') return value
  const exact = chineseUiKeys.get(value)
  if (exact) return translateMessage(language, exact)
  const localize = (text: string) => translateStoredUiText(language, text)
  let match = value.match(/^操作失败：([\s\S]+)$/u)
  if (match) return translateMessage(language, 'status.failed', { message: localize(match[1] || '') })
  match = value.match(/^请求失败（([^）]+)）：([\s\S]+)$/u)
  if (match) return translateMessage(language, 'status.requestFailed', { code: match[1] || '', message: localize(match[2] || '') })
  match = value.match(/^已在 (\d+) 页添加(.+)$/u)
  if (match) return translateMessage(language, 'status.annotationsAdded', { count: match[1] || '', annotation: localize(match[2] || '') })
  match = value.match(/^已合并 (\d+) 个文件；请确认页面顺序$/u)
  if (match) return translateMessage(language, "ui.mergedCountFileSConfirmThePageOrder", { count: match[1] || '' })
  match = value.match(/^已新建合并文档并导入 (\d+) 个文件；请确认页面顺序$/u)
  if (match) return translateMessage(language, "ui.createdANewMergedDocumentAndImportedCountFileS", { count: match[1] || '' })
  match = value.match(/^已创建合并文档，已导入 (\d+) 个文件$/u)
  if (match) return translateMessage(language, "ui.createdAMergedDocumentAndImportedCountFileS", { count: match[1] || '' })
  match = value.match(/^已合并 (\d+) 个文件$/u)
  if (match) return translateMessage(language, "ui.mergedCountFileS", { count: match[1] || '' })
  match = value.match(/^(.+)已添加$/u)
  if (match) return translateMessage(language, 'status.annotationAdded', { annotation: localize(match[1] || '') })
  match = value.match(/^已删除 (\d+) 条批注，可按 Ctrl\/⌘Z 撤销$/u)
  if (match) return translateMessage(language, 'status.annotationsDeleted', { count: match[1] || '' })
  match = value.match(/^已回复：([\s\S]+)$/u)
  if (match) return translateMessage(language, 'status.replied', { reply: localize(match[1] || '') })
  if (value.includes(' · ')) {
    const chunks = value.split(' · ')
    const localized = chunks.map(localize)
    if (localized.some((chunk, index) => chunk !== chunks[index])) return localized.join(' · ')
  }
  match = value.match(/^已保存 · ([\s\S]+)$/u)
  if (match) return translateMessage(language, 'status.saved', { detail: match[1] || '' })
  match = value.match(/^已复制 (\d+) 个字符 · 已智能合并回行$/u)
  if (match) return translateMessage(language, 'status.copied', { count: match[1] || '' })
  match = value.match(/^正在准备打印 (\d+) 页…$/u)
  if (match) return translateMessage(language, 'status.preparingPrint', { count: match[1] || '' })
  match = value.match(/^已发送 (\d+) 页到打印机$/u)
  if (match) return translateMessage(language, 'status.sentPrint', { count: match[1] || '' })
  match = value.match(/^正在准备导出 (\d+) 页…$/u)
  if (match) return translateMessage(language, 'status.preparingExport', { count: match[1] || '' })
  match = value.match(/^已合并导出 (\d+) 页 PDF · ([\s\S]+)$/u)
  if (match) return translateMessage(language, 'status.exportedPdf', { count: match[1] || '', path: match[2] || '' })
  match = value.match(/^已导出 (\d+) 个 PDF 文件 · ([\s\S]+)$/u)
  if (match) return translateMessage(language, 'status.exportedPdfs', { count: match[1] || '', path: match[2] || '' })
  match = value.match(/^已导出 (\d+) 个文件 · ([\s\S]+)$/u)
  if (match) return translateMessage(language, 'status.exportedFiles', { count: match[1] || '', path: match[2] || '' })
  match = value.match(/^正在导出 (\d+)\/(\d+) · 原文档第 (\d+) 页…$/u)
  if (match) return translateMessage(language, 'status.exporting', { completed: match[1] || '', total: match[2] || '', page: match[3] || '' })
  match = value.match(/^已选择：([\s\S]+)$/u)
  if (match) return translateMessage(language, 'status.selected', { detail: match[1] || '' })
  match = value.match(/^已删除 (\d+) 个页面$/u)
  if (match) return translateMessage(language, 'status.deletedPages', { count: match[1] || '' })
  match = value.match(/^图片 (\d+) 个$/u)
  if (match) return translateMessage(language, 'insight.imageCount', { count: match[1] || '' })
  if (value === '检测到页面图像对象') return translateMessage(language, 'insight.pageImageObject')
  match = value.match(/^检测到表格列式文本或统计字段：([\s\S]+)$/u)
  if (match) return translateMessage(language, 'insight.tableFields', { anchor: match[1] || '' })
  match = value.match(/^拼写：([\s\S]+)$/u)
  if (match) return translateMessage(language, 'insight.spelling', { word: match[1] || '' })
  return value
}
